fn determine_winner(a: i8, b: i8, c: i8, d: i8) -> String {
    // Helper to compute the final score for a participant.
    fn score(p: i32, t: i32) -> i32 {
        let option1 = 3 * p / 10;
        let option2 = p - (p * t) / 250;
        option1.max(option2)
    }

    let s1 = score(a as i32, b as i32);
    let s2 = score(c as i32, d as i32);

    if s1 > s2 {
        "Misha".to_string()
    } else if s2 > s1 {
        "Vasya".to_string()
    } else {
        "Tie".to_string()
    }
}

